import os
import time
import json
import csv
import platform
import cv2
import numpy as np
from rembg import remove
from PIL import Image

def benchmark_macbook_m1_pipeline():
    print(f"\n=======================================================")
    print(f"🍏 [Talha's M1 Benchmark Studio] Running on: {platform.platform()}")
    print(f"=======================================================")

    results_dir = "outputs/benchmarks"
    os.makedirs(results_dir, exist_ok=True)
    
    # Locate a sample image from the dataset generated by Step 1
    sample_img_path = "dataset/photos/P01_stove_knob/view1_sharp.jpg"
    if not os.path.exists(sample_img_path):
        print(f"⚠️ Sample image not found at {sample_img_path}. Run step1_build_dataset.py first!")
        return

    metrics_log = []

    # 1. Benchmark OpenCV Blur Detection (Laplacian Variance)
    print("\n[1/3] Benchmarking OpenCV Blur Detection...")
    img_cv = cv2.imread(sample_img_path)
    gray = cv2.cvtColor(img_cv, cv2.COLOR_BGR2GRAY)

    start_time = time.time()
    for _ in range(50):  # Run 50 iterations to get accurate average runtime
        blur_score = float(cv2.Laplacian(gray, cv2.CV_64F).var())
    blur_elapsed_ms = ((time.time() - start_time) / 50.0) * 1000.0
    print(f"  • Average Blur Check Time: {blur_elapsed_ms:.2f} ms (Score: {blur_score:.1f})")
    metrics_log.append({"operation": "OpenCV Blur Check", "avg_time_ms": round(blur_elapsed_ms, 2)})

    # 2. Benchmark AI Background Removal (rembg / U2-Net)
    print("\n[2/3] Benchmarking Neural Network Background Removal (rembg)...")
    pil_img = Image.open(sample_img_path).convert("RGBA")

    start_time = time.time()
    segmented_img = remove(pil_img)  # Runs on CPU/MPS on Apple Silicon
    rembg_elapsed_ms = (time.time() - start_time) * 1000.0
    
    clean_out = os.path.join(results_dir, "m1_segmented_test.png")
    segmented_img.save(clean_out)
    print(f"  • rembg Masking Runtime: {rembg_elapsed_ms:.2f} ms")
    metrics_log.append({"operation": "AI Background Removal (rembg)", "avg_time_ms": round(rembg_elapsed_ms, 2)})

    # 3. Save Apple Silicon Feasibility Report (Section 8.1)
    report = {
        "hardware_platform": platform.platform(),
        "processor": platform.processor(),
        "python_version": platform.python_version(),
        "apple_silicon_optimized": True,
        "benchmark_metrics": metrics_log
    }

    report_path = os.path.join(results_dir, "m1_feasibility_report.json")
    with open(report_path, "w") as f:
        json.dump(report, f, indent=2)

    print(f"\n✅ M1 Feasibility Benchmark Complete!")
    print(f"✅ Saved audit log to: {report_path}")
    print(f"=======================================================\n")

if __name__ == "__main__":
    benchmark_macbook_m1_pipeline()